1	import React, { useCallback, useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Clients feature: add a client (name + email) and list every client. Opening a client
5	// (client-open-<id>) reveals the projects being done for them — the client's own projects listing,
6	// scoped via its /api/clients/<id>/projects endpoint. Owns its own state; talks to its own
7	// /api/clients endpoints. data-testid anchors follow the spec's conventions.
8	type Client = { id: number; name: string; email: string; outstanding: number };
9	// How the clients list is ordered: alphabetically by name, or by how much each client still owes.
10	type SortKey = 'name' | 'outstanding';
11	type Project = { id: number; name: string; clientId: number; clientName: string };
12	type Contact = {
13	  id: number;
14	  clientId: number;
15	  name: string;
16	  email: string;
17	  role: string;
18	  primary: boolean;
19	};
20	type ClientSummary = { projectCount: number; contactCount: number };
21	type StatementInvoice = { id: number; projectId: number; amountDue: number };
22	type ClientStatement = { invoices: StatementInvoice[]; outstandingTotal: number };
23	
24	// Money, the way every invoice figure is shown across the app: a dollar sign and two decimals.
25	function money(amount: number): string {
26	  return `$${Number(amount).toLocaleString('en-US', {
27	    minimumFractionDigits: 2,
28	    maximumFractionDigits: 2,
29	  })}`;
30	}
31	
32	// Every client (and contact) needs a proper email. Same shape the server enforces (see CreateClient
33	// / CreateContact) so the UI and the API agree on what "valid" means.
34	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
35	function isValidEmail(value: string): boolean {
36	  return EMAIL_RE.test(value.trim());
37	}
38	
39	// Load a JSON resource from `url` into state, refetching whenever the url changes, and hand back a
40	// `reload` for callers that mutate the resource and need to pull the fresh version. Every client
41	// panel reads one url this way, so this is where that fetch-into-state pattern lives once.
42	function useJsonResource<T>(url: string, initial: T): [T, () => Promise<void>] {
43	  const [data, setData] = useState<T>(initial);
44	  const reload = useCallback(async () => {
45	    const res = await fetch(url);
46	    setData(await res.json());
47	  }, [url]);
48	  useEffect(() => {
49	    void reload();
50	  }, [reload]);
51	  return [data, reload];
52	}
53	
54	// A client's statement: all of their invoices in one place, each with what is still owed on it, and
55	// the total still owed across them all. Kept behind an opener so the client detail stays compact.
56	// Owns its own statement state, scoped to the one client it is showing; talks to that client's own
57	// /api/clients/<id>/statement endpoint.
58	function ClientStatement({ client }: { client: Client }) {
59	  const [statement] = useJsonResource<ClientStatement | null>(
60	    `/api/clients/${client.id}/statement`,
61	    null,
62	  );
63	  const [open, setOpen] = useState(false);
64	
65	  return (
66	    <section data-testid="client-statement">
67	      <button data-testid="client-statement-open" onClick={() => setOpen(true)}>
68	        Statement
69	      </button>
70	      {open && statement && (
71	        <>
72	          <table data-testid="client-statement-table">
73	            <tbody>
74	              {statement.invoices.map((inv) => (
75	                <tr key={inv.id} data-testid={`statement-invoice-row-${inv.id}`}>
76	                  <td data-testid="statement-invoice-due">{money(inv.amountDue)}</td>
77	                </tr>
78	              ))}
79	            </tbody>
80	          </table>
81	          <p data-testid="client-outstanding-total">{money(statement.outstandingTotal)}</p>
82	        </>
83	      )}
84	    </section>
85	  );
86	}
87	
88	// A client's at-a-glance counts: how many projects and contacts are kept for them. Owns its own
89	// summary state, scoped to the one client it is showing; talks to that client's own
90	// /api/clients/<id>/summary endpoint.
91	function ClientSummaryBadges({ client }: { client: Client }) {
92	  const [summary] = useJsonResource<ClientSummary>(`/api/clients/${client.id}/summary`, {
93	    projectCount: 0,
94	    contactCount: 0,
95	  });
96	
97	  return (
98	    <section data-testid="client-summary">
99	      <span data-testid="client-projects-count">{summary.projectCount}</span>
100	      <span data-testid="client-contacts-count">{summary.contactCount}</span>
101	    </section>
102	  );
103	}
104	
105	// The add-a-contact form: name, email and role, all required, with the same email check the server
106	// runs. Owns only its own field state and clears itself once the parent has taken the new contact.
107	function ContactForm({
108	  onAdd,
109	}: {
110	  onAdd: (contact: { name: string; email: string; role: string }) => Promise<void>;
111	}) {
112	  const [name, setName] = useState('');
113	  const [email, setEmail] = useState('');
114	  const [role, setRole] = useState('');
115	  const [emailError, setEmailError] = useState('');
116	
117	  async function submit(e: React.FormEvent) {
118	    e.preventDefault();
119	    if (!name.trim() || !email.trim() || !role.trim()) {
120	      return;
121	    }
122	    if (!isValidEmail(email)) {
123	      setEmailError('Enter a valid email address.');
124	      return;
125	    }
126	    setEmailError('');
127	    await onAdd({ name, email, role });
128	    setName('');
129	    setEmail('');
130	    setRole('');
131	  }
132	
133	  return (
134	    <form data-testid="contact-form" onSubmit={submit}>
135	      <input
136	        data-testid="contact-form-name"
137	        placeholder="Name"
138	        value={name}
139	        onChange={(e) => setName(e.target.value)}
140	      />
141	      <input
142	        data-testid="contact-form-email"
143	        placeholder="Email"
144	        value={email}
145	        onChange={(e) => setEmail(e.target.value)}
146	      />
147	      {emailError && (
148	        <p data-testid="contact-form-email-error" role="alert">
149	          {emailError}
150	        </p>
151	      )}
152	      <input
153	        data-testid="contact-form-role"
154	        placeholder="Role"
155	        value={role}
156	        onChange={(e) => setRole(e.target.value)}
157	      />
158	      <button data-testid="contact-form-submit" type="submit">
159	        Add contact
160	      </button>
161	    </form>
162	  );
163	}
164	
165	// The contacts list itself: a row per contact with a control to promote it to the client's primary.
166	function ContactsTable({
167	  contacts,
168	  onMakePrimary,
169	}: {
170	  contacts: Contact[];
171	  onMakePrimary: (id: number) => void;
172	}) {
173	  return (
174	    <table data-testid="client-contacts-table">
175	      <tbody>
176	        {contacts.map((ct) => (
177	          <tr key={ct.id} data-testid={`contact-row-${ct.id}`}>
178	            <td data-testid="contact-name">{ct.name}</td>
179	            <td data-testid="contact-email">{ct.email}</td>
180	            <td data-testid="contact-role">{ct.role}</td>
181	            <td>
182	              <button data-testid={`contact-primary-${ct.id}`} onClick={() => onMakePrimary(ct.id)}>
183	                Make primary
184	              </button>
185	            </td>
186	          </tr>
187	        ))}
188	      </tbody>
189	    </table>
190	  );
191	}
192	
193	// A client's contacts: the people the user keeps for them (name, email, role), with a form to add
194	// another. Owns its own contact state, scoped to the one client it is showing; talks to that
195	// client's own /api/clients/<id>/contacts endpoints. The form and the table are their own pieces so
196	// this stays a thin coordinator: load, add, promote, show who is primary.
197	function ClientContacts({ client }: { client: Client }) {
198	  const [contacts, reload] = useJsonResource<Contact[]>(`/api/clients/${client.id}/contacts`, []);
199	
200	  async function addContact(contact: { name: string; email: string; role: string }) {
201	    await fetch(`/api/clients/${client.id}/contacts`, {
202	      method: 'POST',
203	      headers: { 'Content-Type': 'application/json' },
204	      body: JSON.stringify(contact),
205	    });
206	    await reload();
207	  }
208	
209	  // Pick this contact as the client's one main contact, then refresh so the new primary shows.
210	  async function makePrimary(id: number) {
211	    await fetch(`/api/contacts/${id}/primary`, { method: 'POST' });
212	    await reload();
213	  }
214	
215	  const primary = contacts.find((ct) => ct.primary) ?? null;
216	
217	  return (
218	    <section data-testid="client-contacts">
219	      <p data-testid="client-primary-contact">{primary ? primary.name : ''}</p>
220	      <ContactForm onAdd={addContact} />
221	      <ContactsTable contacts={contacts} onMakePrimary={makePrimary} />
222	    </section>
223	  );
224	}
225	
226	// A client's detail: the projects being done for them. Owns its own project state, scoped to the one
227	// client it is showing. Reuses the project-row-<id>/project-name anchors in a client-scoped table.
228	// Shows only the client's ACTIVE projects by default (scope=active); the show-all toggle asks the
229	// server for everything (scope=all), so the finished and hidden (archived) ones appear too.
230	function ClientProjects({ client }: { client: Client }) {
231	  const [showAll, setShowAll] = useState(false);
232	  const [projects] = useJsonResource<Project[]>(
233	    `/api/clients/${client.id}/projects?scope=${showAll ? 'all' : 'active'}`,
234	    [],
235	  );
236	
237	  return (
238	    <section data-testid="client-projects">
239	      <button data-testid="client-projects-show-all" onClick={() => setShowAll((v) => !v)}>
240	        {showAll ? 'Show only active' : 'Show finished and hidden too'}
241	      </button>
242	      <table data-testid="client-projects-table">
243	        <tbody>
244	          {projects.map((p) => (
245	            <tr key={p.id} data-testid={`project-row-${p.id}`}>
246	              <td data-testid="project-name">{p.name}</td>
247	            </tr>
248	          ))}
249	        </tbody>
250	      </table>
251	    </section>
252	  );
253	}
254	
255	// A name-and-email form for a client, used to add one and reusable for correcting one. `testid` is
256	// the anchor prefix (its fields are `${testid}-name` / `-email` / `-email-error` / `-submit`), so a
257	// second instance (e.g. an edit form) just passes a different prefix. Validates the email format the
258	// way the server does; `onSubmit` returns an error string to show (e.g. a duplicate the server
259	// rejected) or null on success, in which case the form clears back to its initial values.
260	function ClientForm({
261	  testid,
262	  submitLabel,
263	  initial = { name: '', email: '' },
264	  onSubmit,
265	}: {
266	  testid: string;
267	  submitLabel: string;
268	  initial?: { name: string; email: string };
269	  onSubmit: (values: { name: string; email: string }) => Promise<string | null>;
270	}) {
271	  const [name, setName] = useState(initial.name);
272	  const [email, setEmail] = useState(initial.email);
273	  const [emailError, setEmailError] = useState('');
274	
275	  async function submit(e: React.FormEvent) {
276	    e.preventDefault();
277	    if (!isValidEmail(email)) {
278	      setEmailError('Enter a valid email address.');
279	      return;
280	    }
281	    const error = await onSubmit({ name, email });
282	    if (error) {
283	      setEmailError(error);
284	      return;
285	    }
286	    setEmailError('');
287	    setName(initial.name);
288	    setEmail(initial.email);
289	  }
290	
291	  return (
292	    <form data-testid={testid} onSubmit={submit}>
293	      <input
294	        data-testid={`${testid}-name`}
295	        placeholder="Name"
296	        value={name}
297	        onChange={(e) => setName(e.target.value)}
298	      />
299	      <input
300	        data-testid={`${testid}-email`}
301	        placeholder="Email"
302	        value={email}
303	        onChange={(e) => setEmail(e.target.value)}
304	      />
305	      {emailError && (
306	        <p data-testid={`${testid}-email-error`} role="alert">
307	          {emailError}
308	        </p>
309	      )}
310	      <button data-testid={`${testid}-submit`} type="submit">
311	        {submitLabel}
312	      </button>
313	    </form>
314	  );
315	}
316	
317	// The client list: a row per client with controls to open its detail or archive it.
318	function ClientsTable({
319	  clients,
320	  onOpen,
321	  onEdit,
322	  onArchive,
323	}: {
324	  clients: Client[];
325	  onOpen: (id: number) => void;
326	  onEdit: (id: number) => void;
327	  onArchive: (id: number) => void;
328	}) {
329	  return (
330	    <table data-testid="clients-table">
331	      <tbody>
332	        {clients.map((c) => (
333	          <tr key={c.id} data-testid={`client-row-${c.id}`}>
334	            <td data-testid="client-name">{c.name}</td>
335	            <td data-testid="client-email">{c.email}</td>
336	            <td data-testid="client-outstanding">{money(c.outstanding)}</td>
337	            <td>
338	              <button data-testid={`client-open-${c.id}`} onClick={() => onOpen(c.id)}>
339	                Open
340	              </button>
341	              <button data-testid={`client-edit-${c.id}`} onClick={() => onEdit(c.id)}>
342	                Edit
343	              </button>
344	              <button data-testid={`client-archive-${c.id}`} onClick={() => onArchive(c.id)}>
345	                Archive
346	              </button>
347	            </td>
348	          </tr>
349	        ))}
350	      </tbody>
351	    </table>
352	  );
353	}
354	
355	function ClientsPage() {
356	  const [clients, reload] = useJsonResource<Client[]>('/api/clients', []);
357	  // Client-side name filter: the list can get long, so a search box narrows it. Case-insensitive
358	  // substring match on the client name; an empty box shows everyone.
359	  const [search, setSearch] = useState('');
360	  // How the list is ordered: by name (default) or by how much each client owes (most first).
361	  const [sort, setSort] = useState<SortKey>('name');
362	  const [openId, setOpenId] = useState<number | null>(null);
363	  // Which client (if any) is being corrected: opening the edit form seeds it with that client's
364	  // current name and email so the user tweaks rather than retypes.
365	  const [editingId, setEditingId] = useState<number | null>(null);
366	
367	  // Two clients cannot share an email; the server rejects a duplicate, so surface it and keep the
368	  // form as-is rather than clearing or reloading (nothing was added).
369	  async function addClient(values: { name: string; email: string }): Promise<string | null> {
370	    const res = await fetch('/api/clients', {
371	      method: 'POST',
372	      headers: { 'Content-Type': 'application/json' },
373	      body: JSON.stringify(values),
374	    });
375	    if (!res.ok) {
376	      return 'A client with this email already exists.';
377	    }
378	    await reload();
379	    return null;
380	  }
381	
382	  // Correct a client's name or email. The server rejects a duplicate email (against another
383	  // client), so surface it and keep the form open; on success reload and close the edit form.
384	  async function editClient(
385	    id: number,
386	    values: { name: string; email: string },
387	  ): Promise<string | null> {
388	    const res = await fetch(`/api/clients/${id}`, {
389	      method: 'PUT',
390	      headers: { 'Content-Type': 'application/json' },
391	      body: JSON.stringify(values),
392	    });
393	    if (!res.ok) {
394	      return 'A client with this email already exists.';
395	    }
396	    await reload();
397	    setEditingId(null);
398	    return null;
399	  }
400	
401	  // Tuck a client away: archived clients are retained server-side but drop off this list and out of
402	  // the search. Reloading after archiving is enough — the /api/clients list excludes them.
403	  async function archive(id: number) {
