      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tagId: Number(tagToAdd) }),
    });
    setTagToAdd('');
    await loadTags();
  }

  async function removeTag(id: number) {
    await fetch(`/api/projects/${project.id}/tags/${id}/remove`, { method: 'POST' });
    await loadTags();
  }

